  if (k === 1) { const v = pick([0.25, 0.5, 1, 1.5, 2]); return { q: `${fmt(v)} L = ? mL`, ans: v * 1000, unit: "mL" }; }
  if (k === 2) { const [n, ml] = pick(SPOON); const c = pick([2, 3, 4, 6]); return { q: `${c} ${n.split("(")[1].replace(")", "")} = ? mL`, ans: c * ml, unit: "mL" }; }
